<template>
  <div class="course-player" ref="coursePlayer">
    <aside class="sidebar" :class="{ collapsed: sidebarCollapsed }">
      <button v-if="!sidebarCollapsed" class="sidebar-hamburger" @click="sidebarCollapsed = true" aria-label="Close contents">
        <Bars3Icon class="w-5 h-5" />
      </button>
      <div class="sidebar-header">
        <h3 v-if="!sidebarCollapsed">Contents</h3>
      </div>
      <nav v-if="!sidebarCollapsed && course" class="course-nav">
        <div v-for="section in course.sections" :key="section.id" class="section">
          <div class="section-header" @click="toggleSection(section.id)">
            <span>{{ section.orderIndex }}. {{ section.title }}</span>
            <span class="chevron">{{ expandedSections[section.id] ? '▼' : '▶' }}</span>
          </div>
          <ul v-show="expandedSections[section.id]" class="lessons">
            <li v-for="lesson in section.lessons" :key="lesson.id" 
                class="lesson"
                :class="{ active: currentLesson?.id === lesson.id }"
                @click="selectLesson(lesson)">
              <div class="lesson-icon">○</div>
              <div class="lesson-info">
                <div class="lesson-title">{{ lesson.title }}</div>
                <div class="lesson-meta" v-if="lesson.durationSeconds">
                  {{ formatDuration(lesson.durationSeconds) }} video
                </div>
              </div>
            </li>
          </ul>
        </div>
      </nav>
    </aside>

    <main class="main-content">
      <div class="video-container" v-if="currentLesson" ref="videoContainer">
        <video class="video-element" ref="videoElement" @click="togglePlay" :poster="currentLesson.poster || ''">
          <source src="https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4" type="video/mp4">
          Your browser does not support the video tag.
        </video>

        <div class="video-topbar">
          <div class="video-left">
            <button v-if="sidebarCollapsed" class="video-open" @click="sidebarCollapsed = false" aria-label="Open contents">
              <Bars3Icon class="w-5 h-5" />
            </button>
            <div class="breadcrumb">
              <h1>{{ course?.title }}</h1>
              <h2 v-if="currentLesson">{{ currentLesson.title }}</h2>
            </div>
          </div>
          <div class="video-actions">
            <!-- placeholder for like/bookmark/share icons -->
          </div>
          <button v-if="!sidebarCollapsed" class="video-close" @click="sidebarCollapsed = true" aria-label="Close contents">✕</button>
        </div>

        <!-- native/enhanced player controls (Plyr) will render over the video; removed duplicate custom controls -->

      </div>

      <div class="tabs">
        <button class="tab" :class="{ active: activeTab === 'overview' }" @click="activeTab = 'overview'">
          📋 Overview
        </button>
        <button class="tab" :class="{ active: activeTab === 'transcript' }" @click="activeTab = 'transcript'">
          📄 Transcript
        </button>
      </div>

      <div class="tab-content">
        <div v-if="activeTab === 'overview'" class="overview">
          <section class="instructor" v-if="course">
            <h3>Course Overview</h3>
            <p>{{ course.description || 'No description available.' }}</p>
            <div class="course-meta">
              <p><strong>Sections:</strong> {{ course.sections?.length || 0 }}</p>
              <p><strong>Total Lessons:</strong> {{ totalLessons }}</p>
            </div>
          </section>
        </div>
        <div v-if="activeTab === 'transcript'" class="transcript">
          <p>Transcript feature coming soon...</p>
        </div>
      </div>
    </main>
  </div>
</template>

<script>
import axios from 'axios'
import { Bars3Icon } from '@heroicons/vue/24/outline'

export default {
  name: 'CoursePlayer',
  components: {
    Bars3Icon
  },
  data() {
    return {
      course: null,
      currentLesson: null,
      sidebarCollapsed: false,
      expandedSections: {},
      activeTab: 'overview',
      loading: false,
      isPlaying: false,
      isFullscreen: false,
      plyrPlayer: null
    }
  },
  computed: {
    totalLessons() {
      if (!this.course?.sections) return 0
      return this.course.sections.reduce((sum, s) => sum + (s.lessons?.length || 0), 0)
    }
  },
  async created() {
    await this.loadCourse()
  },
  mounted() {
    document.addEventListener('fullscreenchange', this.handleFullscreenChange)
    // initialize an enhanced player once mounted
    this.$nextTick(() => this.initPlayer())
  },
  beforeUnmount() {
    document.removeEventListener('fullscreenchange', this.handleFullscreenChange)
    this.destroyPlayer()
  },
  methods: {
    async loadPlyrFromCDN() {
      return new Promise((resolve, reject) => {
        try {
          if (window.Plyr) return resolve(window.Plyr)
          const cssHref = 'https://cdn.jsdelivr.net/npm/plyr@3.7.8/dist/plyr.css'
          const jsSrc = 'https://cdn.jsdelivr.net/npm/plyr@3.7.8/dist/plyr.min.js'
          if (!document.querySelector(`link[href="${cssHref}"]`)) {
            const link = document.createElement('link')
            link.rel = 'stylesheet'
            link.href = cssHref
            document.head.appendChild(link)
          }
          if (window.Plyr) return resolve(window.Plyr)
          if (!document.querySelector(`script[src="${jsSrc}"]`)) {
            const s = document.createElement('script')
            s.src = jsSrc
            s.onload = () => resolve(window.Plyr)
            s.onerror = (e) => reject(e)
            document.body.appendChild(s)
          } else {
            const existing = document.querySelector(`script[src="${jsSrc}"]`)
            existing.addEventListener('load', () => resolve(window.Plyr))
            existing.addEventListener('error', (e) => reject(e))
          }
        } catch (err) {
          reject(err)
        }
      })
    },

    async initPlayer() {
      try {
        const video = this.$refs.videoElement
        if (!video) return
        const PlyrCtor = window.Plyr || await this.loadPlyrFromCDN()
        if (!PlyrCtor) return
        this.plyrPlayer = new PlyrCtor(video, {
          controls: ['play', 'progress', 'current-time', 'mute', 'volume', 'settings', 'fullscreen']
        })
        
        // Intercept fullscreen control to use document-level fullscreen
        try {
          const controls = this.plyrPlayer.elements && this.plyrPlayer.elements.controls
          const fsBtn = controls && (controls.querySelector('[data-plyr="fullscreen"]') || controls.querySelector('.plyr__control--fullscreen'))
          if (fsBtn) {
            this._plyrFsBtn = fsBtn
            this._plyrFsHandler = (ev) => {
              ev.preventDefault()
              ev.stopPropagation()
              if (!document.fullscreenElement) {
                if (document.documentElement.requestFullscreen) {
                  document.documentElement.requestFullscreen().catch(() => {})
                }
              } else {
                if (document.exitFullscreen) {
                  document.exitFullscreen().catch(() => {})
                }
              }
            }
            fsBtn.addEventListener('click', this._plyrFsHandler, true)
          }
        } catch (e) {
          console.warn('Failed to intercept Plyr fullscreen button', e)
        }
      } catch (e) {
        console.warn('Plyr init failed', e)
      }
    },

    destroyPlayer() {
      try {
        if (this._plyrFsBtn && this._plyrFsHandler) {
          try { this._plyrFsBtn.removeEventListener('click', this._plyrFsHandler, true) } catch (e) {}
          this._plyrFsBtn = null
          this._plyrFsHandler = null
        }
        if (this.plyrPlayer) {
          this.plyrPlayer.destroy()
          this.plyrPlayer = null
        }
      } catch (e) {
        // ignore
      }
    },
    async loadCourse() {
      this.loading = true
      // Using made-up, AI-themed dummy data
      this.course = {
        id: 'a1',
        slug: 'ai-for-beginners',
        title: 'AI for Beginners: Building Your First Bot',
        description: 'Kickstart your journey into artificial intelligence by creating your first chatbot and exploring the basics of machine learning.',
        published: true,
        sections: [
          {
            id: 's1',
            orderIndex: 1,
            title: 'Getting Started with AI',
            description: 'Welcome and setup',
            lessons: [
              {
                id: 'l1',
                orderIndex: 1,
                title: 'What is Artificial Intelligence?',
                summary: 'A fun intro to AI',
                durationSeconds: 75
              },
              {
                id: 'l2',
                orderIndex: 2,
                title: 'Meet Your First Chatbot',
                summary: 'Hands-on bot demo',
                durationSeconds: 110
              }
            ]
          },
          {
            id: 's2',
            orderIndex: 2,
            title: 'Machine Learning Basics',
            description: 'Core ML concepts',
            lessons: [
              {
                id: 'l3',
                orderIndex: 1,
                title: 'How Machines Learn',
                summary: 'Training and data',
                durationSeconds: 130
              },
              {
                id: 'l4',
                orderIndex: 2,
                title: 'Building a Simple Model',
                summary: 'Your first ML model',
                durationSeconds: 145
              }
            ]
          },
          {
            id: 's3',
            orderIndex: 3,
            title: 'Deploying Your Bot',
            description: 'Making your bot available',
            lessons: [
              {
                id: 'l5',
                orderIndex: 1,
                title: 'Testing and Improving',
                summary: 'Iterate and enhance',
                durationSeconds: 120
              },
              {
                id: 'l6',
                orderIndex: 2,
                title: 'Going Live!',
                summary: 'Launch your creation',
                durationSeconds: 90
              }
            ]
          }
        ]
      }
      
      // Expand all sections by default and select first lesson
      if (this.course.sections?.length > 0) {
        this.course.sections.forEach(section => {
          this.expandedSections[section.id] = true
        })
        const firstSection = this.course.sections[0]
        if (firstSection.lessons?.length > 0) {
          this.currentLesson = firstSection.lessons[0]
        }
      }
      this.loading = false
    },
    toggleSection(sectionId) {
      this.expandedSections[sectionId] = !this.expandedSections[sectionId]
    },
    selectLesson(lesson) {
      this.currentLesson = lesson
    },
    formatDuration(seconds) {
      if (!seconds) return '0m 0s'
      const m = Math.floor(seconds / 60)
      const s = seconds % 60
      return `${m}m ${s}s`
    },
    togglePlay() {
      const video = this.$refs.videoElement
      if (video.paused) {
        video.play()
        this.isPlaying = true
      } else {
        video.pause()
        this.isPlaying = false
      }
    },
    toggleFullscreen() {
      const container = this.$refs.coursePlayer
      alert('Toggling fullscreen');
      if (!document.fullscreenElement) {
        container.requestFullscreen().then(() => {
          this.isFullscreen = true
        }).catch(err => {
          console.error('Error attempting to enable fullscreen:', err)
        })
      } else {
        document.exitFullscreen().then(() => {
          this.isFullscreen = false
        })
      }
    },
    handleFullscreenChange() {
      this.isFullscreen = !!document.fullscreenElement
      const container = this.$refs.coursePlayer
      
      // Add/remove class on body to hide navigation components
      if (this.isFullscreen) {
        document.body.classList.add('player-fullscreen')
      } else {
        document.body.classList.remove('player-fullscreen')
      }
      
      if (container && container.classList) {
        if (this.isFullscreen) container.classList.add('is-fullscreen')
        else container.classList.remove('is-fullscreen')

        // Toggle accessibility states for tabs when entering/exiting fullscreen
        try {
          const tabs = container.querySelector('.tabs')
          const tabContent = container.querySelector('.tab-content')
          if (tabs) tabs.setAttribute('aria-hidden', this.isFullscreen ? 'true' : 'false')
          if (tabContent) tabContent.setAttribute('aria-hidden', this.isFullscreen ? 'true' : 'false')
        } catch (e) {
          // ignore if DOM queries fail
        }
        
        // Update Plyr's fullscreen button icon manually with custom class
        try {
          if (this._plyrFsBtn) {
            if (this.isFullscreen) {
              this._plyrFsBtn.classList.add('custom-fs-active')
            } else {
              this._plyrFsBtn.classList.remove('custom-fs-active')
            }
          }
        } catch (e) {
          // ignore
        }
      }
    }
  }
}
</script>

<style scoped>
/* Custom fullscreen button icon control - use :deep() to target Plyr elements */
:deep(.custom-fs-active .icon--not-pressed) {
  display: none !important;
}
:deep(.custom-fs-active .icon--pressed) {
  display: block !important;
}
:deep(.custom-fs-active .label--not-pressed) {
  display: none !important;
}
:deep(.custom-fs-active .label--pressed) {
  display: block !important;
}

:deep(button:not(.custom-fs-active) .icon--pressed) {
  display: none !important;
}
:deep(button:not(.custom-fs-active) .icon--not-pressed) {
  display: block !important;
}
:deep(button:not(.custom-fs-active) .label--pressed) {
  display: none !important;
}
:deep(button:not(.custom-fs-active) .label--not-pressed) {
  display: block !important;
}

.course-player {
  display: flex;
  height: 100vh;
  overflow: hidden;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  background: #000;
  color: #fff;
}

/* Fullscreen mode: expand video container and hide tabs */
.course-player:fullscreen,
.course-player:-webkit-full-screen,
.course-player:-moz-full-screen,
.course-player:-ms-fullscreen {
  width: 100vw;
  height: 100vh;
}

.course-player:fullscreen .main-content,
.course-player:-webkit-full-screen .main-content,
.course-player:-moz-full-screen .main-content,
.course-player:-ms-fullscreen .main-content {
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.course-player:fullscreen .video-container,
.course-player:-webkit-full-screen .video-container,
.course-player:-moz-full-screen .video-container,
.course-player:-ms-fullscreen .video-container {
  flex: 0 0 auto;
  height: auto;
  max-height: 100%;
}

.course-player:fullscreen .tabs,
.course-player:-webkit-full-screen .tabs,
.course-player:-moz-full-screen .tabs,
.course-player:-ms-fullscreen .tabs,
.course-player:fullscreen .tab-content,
.course-player:-webkit-full-screen .tab-content,
.course-player:-moz-full-screen .tab-content,
.course-player:-ms-fullscreen .tab-content {
  display: none !important;
  visibility: hidden !important;
  height: 0 !important;
  overflow: hidden !important;
  pointer-events: none !important;
}

/* Also support JS-driven class toggling for container-fullscreen behavior */
.course-player.is-fullscreen .main-content {
  justify-content: center;
}

.course-player.is-fullscreen .video-container {
  flex: 0 0 auto;
  height: auto;
  max-height: 100%;
}

.course-player.is-fullscreen .tabs,
.course-player.is-fullscreen .tab-content {
  display: none !important;
  visibility: hidden !important;
  height: 0 !important;
  overflow: hidden !important;
  pointer-events: none !important;
}

.global-hamburger {
  position: fixed;
  left: 16px;
  top: 16px;
  z-index: 1000;
  width: 40px;
  height: 40px;
  border-radius: 4px;
  background: rgba(255,255,255,0.08);
  color: #fff;
  border: 1px solid rgba(255,255,255,0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: left 0.3s;
}
.global-hamburger:hover {
  background: rgba(255,255,255,0.12);
}
.hamburger-icon { font-size: 18px; }

.sidebar-hamburger {
  position: absolute;
  left: 12px;
  top: 12px;
  z-index: 100;
  width: 40px;
  height: 40px;
  border-radius: 4px;
  background: rgba(255,255,255,0.08);
  color: #fff;
  border: 1px solid rgba(255,255,255,0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}
.sidebar-hamburger:hover {
  background: rgba(255,255,255,0.12);
}

.video-open {
  width: 40px;
  height: 40px;
  border-radius: 4px;
  background: rgba(255,255,255,0.08);
  color: #fff;
  border: 1px solid rgba(255,255,255,0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  margin-right: 12px;
  flex-shrink: 0;
}
.video-open:hover {
  background: rgba(255,255,255,0.12);
}

.sidebar {
  width: 360px;
  background: #2c2f33;
  display: flex;
  flex-direction: column;
  transition: width 0.3s, opacity 0.3s;
  overflow-y: auto;
  flex-shrink: 0;
  position: relative;
}

.sidebar.collapsed {
  width: 0;
  opacity: 0;
  overflow: hidden;
}

.sidebar-header {
  display: flex;
  align-items: center;
  padding: 16px;
  padding-left: 64px;
  border-bottom: 1px solid #444;
}

.toggle-btn {
  background: transparent;
  border: none;
  color: #fff;
  font-size: 20px;
  cursor: pointer;
  padding: 8px;
}

.sidebar h3 {
  margin: 0 0 0 12px;
  font-size: 18px;
}

.course-nav {
  flex: 1;
  overflow-y: auto;
}

.section {
  border-bottom: 1px solid #444;
}

.section-header {
  padding: 16px;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-weight: 500;
  background: #23272a;
}

.section-header:hover {
  background: #2c2f33;
}

.chevron {
  font-size: 12px;
  color: #aaa;
}

.lessons {
  list-style: none;
  margin: 0;
  padding: 0;
}

.lesson {
  display: flex;
  gap: 12px;
  padding: 12px 16px;
  cursor: pointer;
  border-left: 3px solid transparent;
}

.lesson:hover {
  background: #2c2f33;
}

.lesson.active {
  background: #3a3f44;
  border-left-color: #0a66c2;
}

.lesson-icon {
  font-size: 18px;
  color: #888;
}

.lesson.active .lesson-icon {
  color: #0a66c2;
}

.lesson-info {
  flex: 1;
}

.lesson-title {
  font-size: 14px;
  margin-bottom: 4px;
}

.lesson-meta {
  font-size: 12px;
  color: #aaa;
}

.main-content {
  flex: 1;
  display: flex;
  flex-direction: column;
  overflow-y: auto;
  min-height: 0;
}

.content-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 16px 24px;
  background: #1a1a1a;
  border-bottom: 1px solid #333;
}

.breadcrumb {
  text-align: left;
  flex: 1;
}

.breadcrumb h1 {
  font-size: 16px;
  margin: 0 0 4px 0;
  color: #aaa;
  text-align: left;
}

.breadcrumb h2 {
  font-size: 20px;
  margin: 0;
  font-weight: 600;
  text-align: left;
}

.stats {
  display: flex;
  gap: 16px;
}

.stat-item {
  font-size: 14px;
  color: #aaa;
}

.video-container {
  background: #000;
  width: 100%;
  flex: 0 0 auto;
  display: flex;
  justify-content: center;
  position: relative;
  max-width: 100%;
