}

.video-topbar .breadcrumb h2 {
  margin: 0;
  font-size: 18px;
  font-weight: 600;
}

.video-close {
  background: rgba(255,255,255,0.06);
  border: none;
  color: #fff;
  padding: 8px 10px;
  border-radius: 18px;
