}

.spacer { flex: 1 }

.tabs {
  display: flex;
  gap: 0;
  background: #f5f5f5;
  border-bottom: 1px solid #ddd;
  padding: 0 24px;
}

.tab {
  background: transparent;
  border: none;
  color: #666;
  padding: 16px 24px;
  cursor: pointer;
  border-bottom: 3px solid transparent;
