}

.tab-content {
  flex: 1;
  padding: 24px;
  background: #fff;
  overflow-y: auto;
  min-height: 0;
  color: #333;
}

.overview, .transcript {
  max-width: 800px;
}

.instructor h3 {
  margin: 0 0 16px 0;
  font-size: 20px;
  color: #000;
}

.course-meta {
  margin-top: 16px;
  padding-top: 16px;
  border-top: 1px solid #ddd;
}

.course-meta p {
  margin: 8px 0;
  color: #555;
}
</style>
